insert into public.projects (slug, title, tagline, categories, is_new, cover, description, youtube, gallery, position) values
('mi-mama-queria-que-estudiara', '{"es":"Mi Mamá Quería Que Estudiara","en":"Mi Mamá Quería Que Estudiara"}'::jsonb, '{"es":"Diseño de marca · Podcast","en":"Brand design · Podcast"}'::jsonb, array['branding']::text[], true, '{"src":"/work/naka/cover.png","w":1351,"h":1440}'::jsonb, '[{"es":"La creación de la identidad de marca para «Mi mamá quería que estudiara», un podcast conducido por Cristianghost y Janojey, dos de las figuras más reconocidas del streaming en Chile.","en":"Brand identity for “Mi mamá quería que estudiara”, a podcast hosted by Cristianghost and Janojey, two of the best-known streamers in Chile."},{"es":"El objetivo fue construir un universo visual que representara la sinergia y el humor de ambos creadores para su nuevo podcast.","en":"The goal was to build a visual universe that captures the chemistry and humor of both creators for their new show."}]'::jsonb, '91Z9RTg4pLE', '[{"src":"/work/naka/1.png","w":1582,"h":1187},{"src":"/work/naka/2.png","w":4745,"h":2663},{"src":"/work/naka/3.png","w":4745,"h":2694},{"src":"/work/naka/4.png","w":4745,"h":2694}]'::jsonb, 0),
('parque-nacional-nevado-de-tres-cruces', '{"es":"Parque Nacional Nevado de Tres Cruces","en":"Nevado de Tres Cruces National Park"}'::jsonb, '{"es":"Branding","en":"Branding"}'::jsonb, array['branding']::text[], true, '{"src":"/work/tres-cruces/cover.png","w":4745,"h":2694}'::jsonb, '[{"es":"El Parque Nacional Nevado de Tres Cruces es un santuario natural en la Región de Atacama, Chile, donde la inmensidad del altiplano se fusiona con paisajes de salares, lagunas y cumbres nevadas.","en":"Nevado de Tres Cruces National Park is a natural sanctuary in the Atacama Region of Chile, where the vast highlands meet salt flats, lagoons and snowy peaks."},{"es":"Tomando como inspiración la majestuosidad de la zona, se elaboró un logotipo, paleta de colores y mascota para crear una nueva identidad de marca.","en":"Inspired by the grandeur of the area, I designed a logo, color palette and mascot to create a new brand identity."}]'::jsonb, null, '[{"src":"/work/tres-cruces/1.png","w":2462,"h":1476},{"src":"/work/tres-cruces/2.png","w":4354,"h":2694},{"src":"/work/tres-cruces/3.png","w":4686,"h":2694},{"src":"/work/tres-cruces/4.png","w":4745,"h":2694}]'::jsonb, 1),
('zoo-nacional-condor', '{"es":"ZOO Nacional: Rehabilitación de un Cóndor","en":"National Zoo: Rehabilitating a Condor"}'::jsonb, '{"es":"Diseño de información","en":"Information design"}'::jsonb, array['info']::text[], true, '{"src":"/work/zoo/cover.png","w":2400,"h":1600}'::jsonb, '[{"es":"El Zoológico Nacional, dentro del Parquemet, alberga cerca de 1.000 animales de unas 125 especies. Su programa de Rehabilitación busca rescatar, tratar y reinsertar fauna nativa herida, como el cóndor andino.","en":"The National Zoo, inside Parquemet, is home to around 1,000 animals from about 125 species. Its rehabilitation program rescues, treats and releases injured native wildlife such as the Andean condor."},{"es":"El desafío fue diseñar el punto de partida de la historia: la llegada de un cóndor herido. Transformar un momento de diagnóstico clínico, potencialmente complejo y estático, en una experiencia interactiva y comprensible para todos los visitantes.","en":"The challenge was to design the start of the story: the arrival of an injured condor. Turning a complex, static clinical diagnosis into an interactive experience every visitor can understand."}]'::jsonb, null, '[{"src":"/work/zoo/1.png","w":2048,"h":1152},{"src":"/work/zoo/2.png","w":4745,"h":2694},{"src":"/work/zoo/3.png","w":1395,"h":779}]'::jsonb, 2),
('mirador-parquemet', '{"es":"Mirador Parquemet","en":"Parquemet Lookout"}'::jsonb, '{"es":"Diseño de información","en":"Information design"}'::jsonb, array['info']::text[], false, '{"src":"/work/parquemet/cover.png","w":2408,"h":1602}'::jsonb, '[{"es":"El desafío: revelar la riqueza biológica oculta en una de las zonas más áridas del Parque Metropolitano, transformando un espacio de paso en un punto de conexión y aprendizaje, con la visión de la propia comunidad.","en":"The challenge: reveal the hidden biodiversity of one of the driest areas of Santiago’s Metropolitan Park, turning a place people pass through into a point of connection and learning, shaped by the community itself."},{"es":"Se diseñó una pieza de señalética interpretativa que funciona como una ventana narrativa al ecosistema local. La paleta se integra con el paisaje, informando sin generar ruido visual.","en":"I designed an interpretive sign that works as a narrative window into the local ecosystem. Its palette blends into the landscape, informing without visual noise."}]'::jsonb, null, '[{"src":"/work/parquemet/1.png","w":858,"h":432},{"src":"/work/parquemet/2.png","w":869,"h":434},{"src":"/work/parquemet/3.png","w":2048,"h":1152},{"src":"/work/parquemet/4.png","w":4745,"h":2694}]'::jsonb, 3),
('darkwood', '{"es":"Darkwood","en":"Darkwood"}'::jsonb, '{"es":"Edición de video · Inteligencia Artificial","en":"Video editing · AI"}'::jsonb, array['motion']::text[], false, '{"src":"/work/darkwood/cover.png","w":2400,"h":1600}'::jsonb, '[{"es":"DARKWOOD es un tráiler cinematográfico que explora la atmósfera del thriller psicológico y el terror paranormal.","en":"DARKWOOD is a cinematic trailer exploring the mood of psychological thriller and paranormal horror."},{"es":"Sigue a Sam Fisher, un detective cuya investigación en un pueblo remoto lo lleva a cuestionar su propia realidad, al descubrir que una enigmática versión de sí mismo podría ser la única clave para escapar.","en":"It follows Sam Fisher, a detective whose investigation in a remote town makes him question his own reality, as he finds that a strange version of himself may be the only way out."}]'::jsonb, 'D7U2krkC7TQ', '[]'::jsonb, 4),
('cuerpo-completo', '{"es":"Cuerpo Completo","en":"Cuerpo Completo"}'::jsonb, '{"es":"Visualización de datos","en":"Data visualization"}'::jsonb, array['data','info']::text[], false, '{"src":"/work/cuerpo-completo/cover.png","w":505,"h":505}'::jsonb, '[{"es":"Cuerpo Completo traduce un concepto abstracto —el impacto a largo plazo de los hábitos alimenticios— en una experiencia visual y tangible.","en":"Cuerpo Completo turns an abstract idea, the long-term impact of eating habits, into a visual, tangible experience."},{"es":"Usando el «completo», ícono de la alimentación universitaria, como unidad de medida no oficial, la instalación proyecta las consecuencias acumulativas en la salud tras un consumo hipotético de cinco años.","en":"Using the “completo”, the Chilean hot dog that fuels university students, as an unofficial unit of measure, the installation projects the cumulative health effects of five years of hypothetical consumption."}]'::jsonb, null, '[{"src":"/work/cuerpo-completo/1.jpg","w":3024,"h":4032},{"src":"/work/cuerpo-completo/2.jpg","w":3024,"h":4032},{"src":"/work/cuerpo-completo/3.jpg","w":3024,"h":4032},{"src":"/work/cuerpo-completo/4.jpg","w":3024,"h":4032}]'::jsonb, 5),
('disney-plus-ux', '{"es":"Caso de estudio UX/UI: Disney+","en":"UX/UI case study: Disney+"}'::jsonb, '{"es":"UX/UI","en":"UX/UI"}'::jsonb, array['uxui']::text[], false, '{"src":"/work/disneyplus/cover.png","w":2400,"h":1600}'::jsonb, '[{"es":"Tras la fusión de los catálogos de Disney+ y Star+, la plataforma creció masivamente, pero generó una biblioteca extensa e inconexa que presentaba serias dificultades de navegación para sus usuarios.","en":"After merging the Disney+ and Star+ catalogs, the platform grew massively, but its library became large and disconnected, making it hard for users to navigate."}]'::jsonb, null, '[{"src":"/work/disneyplus/1.png","w":2113,"h":1483},{"src":"/work/disneyplus/2.png","w":2048,"h":1437},{"src":"/work/disneyplus/3.png","w":2594,"h":1629}]'::jsonb, 6);
insert into public.site_content (key, value) values
('hero', '{"es":{"eyebrow":"Diseñador integral","title":"Hola, soy Johan.","subtitle":"Diseño marcas, información e interfaces que se entienden a la primera y se sienten bien al usarlas.","cta":"Ver proyectos","scroll":"Desliza"},"en":{"eyebrow":"Multidisciplinary designer","title":"Hi, I’m Johan.","subtitle":"I design brands, information and interfaces that make sense at first sight and feel good to use.","cta":"See work","scroll":"Scroll"}}'::jsonb),
('about', '{"es":{"eyebrow":"Sobre mí","title":"Diseño con propósito, de la idea a la pantalla.","body":["Soy Johan Yanten, diseñador integral de la Universidad Diego Portales. Me muevo entre el branding, el diseño de información, las interfaces y el video.","Me interesa traducir lo complejo en algo claro: datos que se sienten, marcas con personalidad e interfaces que no necesitan instrucciones."]},"en":{"eyebrow":"About","title":"Purposeful design, from idea to screen.","body":["I’m Johan Yanten, a multidisciplinary designer from Universidad Diego Portales. I work across branding, information design, interfaces and video.","I like turning complex things into clear ones: data you can feel, brands with personality and interfaces that need no instructions."]}}'::jsonb),
('contact', '{"es":{"eyebrow":"Contacto","title":"El punto de partida. Hablemos.","subtitle":"¿Prefieres una charla rápida? Escríbeme por Instagram.","cta":"Ir al chat","instagram":"https://www.instagram.com/joandesign.jy/","handle":"@joandesign.jy"},"en":{"eyebrow":"Contact","title":"Every project starts here. Let’s talk.","subtitle":"Prefer a quick chat? Message me on Instagram.","cta":"Open chat","instagram":"https://www.instagram.com/joandesign.jy/","handle":"@joandesign.jy"}}'::jsonb);
